const f = $input.item.json;
const clientName = String(f['Client Name'] || '').trim();
const clientEmail = String(f['Email'] || '').trim().toLowerCase();
const projectName = String(f['Project Name'] || '').trim();
const message = String(f['Message'] || '').replace(/\s+/g, ' ').trim();

// Deterministic validation, before anything costs an AI call or reaches storage
const errors = [];
if (!clientName) errors.push('Missing client name');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(clientEmail)) errors.push('Invalid email');
if (message.length < 15) errors.push('Message too short to classify');

return [{
  json: {
    client_name: clientName,
    client_email: clientEmail,
    project_name: projectName,
    message: message,
    submitted_at: new Date().toISOString(),
    status: 'open',
    validation_errors: errors,
    is_valid: errors.length === 0,
  }
}];

const raw = $input.item.json.text || $input.item.json.output || '';
let parsed;
try {
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : raw);
} catch (e) {
  parsed = null;
}

const ticket = $('Ticket Creation').item.json;
const normalized = $('Normalize Input').item.json;

// Check injection flag from AI or fallback regex
const injectionRegex = /(--|;|\/\*|\*\/|drop\s+table|insert\s+into|delete\s+from|union\s+select|<script>|exec\()/i;
const isInjection = Boolean(parsed?.is_injection || injectionRegex.test(normalized.message));

let category = isInjection ? 'Security / Malicious Input' : (parsed?.category || 'General Inquiry');
let sentiment = parsed?.sentiment || 'Neutral';
let sentimentScore = Number.isFinite(Number(parsed?.sentiment_score)) ? Number(parsed.sentiment_score) : 50;
let priority = isInjection ? 'High' : (parsed?.priority || 'Low');

return [{
  json: {
    id: ticket.id,
    client_name: normalized.client_name,
    client_email: normalized.client_email,
    project_name: normalized.project_name,
    message: normalized.message,
    category: category,
    sentiment: sentiment,
    sentiment_score: sentimentScore,
    priority: priority,
    is_injection: isInjection,
    reasoning: parsed?.reasoning || (isInjection ? 'Malicious injection detected' : 'Standard triage')
  }
}];

const matches = $input.all();
const ticket = $('Parse & Prioritize').item.json;

const validMatches = matches.filter(m => (m.json.pageContent || m.json.content || '').trim().length > 0);
const kbContext = validMatches.map(m => m.json.pageContent || m.json.content).join('\n\n---\n\n');

return [{
  json: {
    ...ticket,
    kb_context: kbContext,
    kb_context_found: validMatches.length > 0
  }
}];

parameters.text:
==You are a support security assistant drafting replies for Petalnex client inquiries.

Client message: {{ $json.message }}
Category: {{ $json.category }}
Is Injection: {{ $json.is_injection }}
Knowledge base context:
{{ $json.kb_context }}

Instructions:
- If Is Injection is true, DO NOT draft a standard customer reply. Output EXACTLY:
WARNING: The client is attempting to inject scripts or malicious SQL payload. Do not execute or copy unchecked parameters.
- If Is Injection is false and knowledge-base context provides the solution, draft a concise, friendly resolution.
- If context does not cover the question, acknowledge the message and state that our specialized support team is reviewing it.
- Return ONLY plain text body. Do NOT wrap output in JSON.

parameters.jsCode:
const responseText = ($input.item.json.text || $input.item.json.output || '').trim();
const ticket = $('Combine KB Context').item.json;

// Escalate on high priority, frustration, security/injection, or non-general inquiries
const requiresEscalation = Boolean(
  ticket.is_injection === true ||
  ticket.category === 'Security / Malicious Input' ||
  ticket.priority === 'High' ||
  ticket.sentiment === 'Frustrated' ||
  ticket.category !== 'General Inquiry'
);

return [{
  json: {
    ...ticket,
    suggested_response: responseText,
    requires_escalation: requiresEscalation
  }
}];

